package com.aicharacter.v3;
/** Recovery follows perfusion, oxygen/energy supply, sleep/rest and continuing mechanical load. No instant timer healing. */
public final class RecoveryEngine{private RecoveryEngine(){}
 public static void advance(WorldState s,double dt,long now){if(s==null||dt<=0||s.body==null)return;if(s.localizedPain==null)s.localizedPain=new LocalizedPainState();double perf=s.circulation==null?1:s.circulation.perfusion,oxy=s.circulation==null?1:s.circulation.oxygenDelivery,energy=s.metabolism==null?s.body.energy/100.0:s.metabolism.availableEnergy;boolean moving=s.girlTravel!=null&&s.girlTravel.active;double rest=moving?.22:1.0;if(s.body.sleepiness>70&&!moving)rest=Math.min(1.18,rest+.12);double supply=Math.max(.08,perf*oxy*Math.max(.12,energy)),recovery=dt/3600.0*supply*rest;LocalizedPainState p=s.localizedPain;double legLoad=s.musculoskeletal==null?0:Math.min(1,s.musculoskeletal.legFatigue*.55+s.musculoskeletal.terrainEffort*.35+s.musculoskeletal.brakingLoad*.25),coreLoad=s.musculoskeletal==null?0:Math.min(1,s.musculoskeletal.coreFatigue*.65);p.leftLeg=heal(p.leftLeg,recovery*(1-legLoad*.78));p.rightLeg=heal(p.rightLeg,recovery*(1-legLoad*.78));p.core=heal(p.core,recovery*(1-coreLoad*.72));p.leftArm=heal(p.leftArm,recovery*.88);p.rightArm=heal(p.rightArm,recovery*.88);p.head=heal(p.head,recovery*.62);double regional=Math.max(Math.max(p.leftLeg,p.rightLeg),Math.max(p.core,Math.max(p.leftArm,Math.max(p.rightArm,p.head))));if(!moving&&regional<.35){s.body.pain=Math.max(0,s.body.pain-recovery*(1-regional)*1.8);s.body.health=Math.min(100,s.body.health+recovery*(1-regional)*.55);}s.body.healInjuryIfRecovered();s.body.clamp();p.lastUpdatedAt=Math.max(p.lastUpdatedAt,now);}
 private static double heal(double v,double amount){return Math.max(0,Math.min(1,v-Math.max(0,amount)*.045));}}
